   827  {
   828      for (Message *message = mReassemblyList.GetHead(); message;)
   829      {
   830          Message *next = message->GetNext();
   831          mReassemblyList.Dequeue(*message);
   832
   833          message->Free();
   834          message = next;
   835      }
